import sys, json, base64, subprocess

# THE TEXT OF A DOCUMENT (file-space, GH #907). `./ingest` asks on
# `in_extract` with `{attachments: [<ref>], path, mime}` and hop `op_id`: a
# PDF about to be born under `path`. This cell declares
# `consumes.body.attachments`, so the colony reads the blob before the script
# runs and `attachments[0]` carries `data_b64` (or `error`). It splits the
# pages and emits exactly ONE message -- the `create` for `./write`, hop
# `{route: in_write, op: create, op_id, caller: ingest, notify: '1'}`, args
# `{path, mime, notify, attachment: 0, derived: [{part, text}, ...]}`, the
# reference passed on so `./write` reads the same blob for the bytes. The
# pages travel in that body only (a body >= 64 KiB becomes a blob by
# itself), never in a hop, a context or a `pending` row (R-FJ-1). Without
# text -- no bytes, no extractor, a failed run -- the `create` goes without
# `derived` and stderr names the code: the file is still born. It keeps
# nothing and writes nothing: no store, no temp file, no disk.
#
# DETERMINISTIC, NO MODEL (OR-FJ-G6, R-27-4 point 4). A PDF goes through
# `pdftotext -layout - -` (poppler) as a subprocess: the bytes on stdin, the
# text on stdout, pages separated by a form feed. argv only, no shell, a
# timeout per call. Missing program -> `no_extractor`; an exit code other
# than 0 -> `extract_failed`. stderr does not count -- poppler warns about
# many readable PDFs.
#
# Knobs: `extract_cmd` (the program, default `pdftotext`), `extract_max_pages`
# (500), `extract_timeout_ms` (30000, below the cell's own timeout).

doc = json.load(sys.stdin)
d = doc.get("body") or {}
P = doc.get("params") or {}
hop = ((doc.get("envelope") or {}).get("header") or {}).get("hop") or {}

PDF = "application/pdf"


def _int(key, default):
    try:
        return int(P.get(key, default))
    except (TypeError, ValueError):
        return default


def split_pages(text, max_pages):
    """`pdftotext` ends every page with a form feed: the last piece after the
    final one is empty. Each page keeps its text without the trailing blank
    lines of the layout."""
    parts = text.split("\f")
    if parts and parts[-1].strip() == "":
        parts = parts[:-1]
    return [p.rstrip() for p in parts][:max_pages]


def extract(mime, data, cmd, timeout_s, max_pages):
    if mime != PDF:
        return {"pages": [], "error": "unsupported_mime"}
    try:
        run = subprocess.run([cmd, "-layout", "-", "-"], input=data, capture_output=True,
                             timeout=timeout_s, env={"PATH": "/usr/bin:/bin", "LC_ALL": "C.UTF-8"})
    except FileNotFoundError:
        return {"pages": [], "error": "no_extractor"}
    except subprocess.TimeoutExpired:
        return {"pages": [], "error": "timeout"}
    except OSError:
        return {"pages": [], "error": "no_extractor"}
    if run.returncode != 0:
        return {"pages": [], "error": "extract_failed"}
    return {"pages": split_pages(run.stdout.decode("utf-8", "replace"), max_pages),
            "tool": "pdftotext"}


def derived_parts(pages):
    return [{"part": i + 1, "text": str(t)} for i, t in enumerate(pages or [])]


def main():
    if str(hop.get("route") or "") != "in_extract":
        sys.stderr.write("file-space/extract: not an in_extract request -- dropped\n")
        return []
    atts = d.get("attachments") if isinstance(d.get("attachments"), list) else []
    entry = atts[0] if atts and isinstance(atts[0], dict) else {}
    ref = {k: v for k, v in entry.items() if k not in ("data_b64", "error")}
    mime = str(d.get("mime") or "")
    err = entry.get("error")
    data = None
    if isinstance(err, dict):
        out = {"pages": [], "error": str(err.get("code") or "store_error")}
    else:
        raw = entry.get("data_b64")
        try:
            data = base64.b64decode(raw if isinstance(raw, str) else "", validate=True)
        except Exception:
            data = None
        if not data:
            out = {"pages": [], "error": "bad_request"}
        else:
            out = extract(mime, data, str(P.get("extract_cmd") or "pdftotext"),
                          max(1, _int("extract_timeout_ms", 30000)) / 1000.0,
                          max(1, _int("extract_max_pages", 500)))
    args = {"path": str(d.get("path") or ""), "mime": mime, "notify": "1", "attachment": 0}
    if out.get("pages"):
        args["derived"] = derived_parts(out["pages"])
    else:
        # `./write` answers a blob it cannot read with that code itself.
        sys.stderr.write("file-space/extract: no text for %s: %s\n"
                         % (args["path"], out.get("error") or "no_pages"))
    op_id = str(hop.get("op_id") or "")
    return [{"header": {"route": "in_write", "op": "create", "op_id": op_id,
                        "caller": "ingest", "notify": "1"},
             "messages": [], "op": "create", "args": args, "attachments": [ref]}]


sys.stdout.write(json.dumps(main()))
